import{_ as e,H as s,f as n,i as p}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"14 | iOS平台如何采集视频画面？","description":"","frontmatter":{},"headers":[{"level":2,"title":"视频框架 ELImage 架构设计","slug":"视频框架-elimage-架构设计","link":"#视频框架-elimage-架构设计","children":[{"level":3,"title":"ELImageInput","slug":"elimageinput","link":"#elimageinput","children":[]},{"level":3,"title":"ELImageOutput","slug":"elimageoutput","link":"#elimageoutput","children":[]},{"level":3,"title":"ELImageProgram","slug":"elimageprogram","link":"#elimageprogram","children":[]},{"level":3,"title":"ELImageTextureFrame","slug":"elimagetextureframe","link":"#elimagetextureframe","children":[]},{"level":3,"title":"ELImageContext","slug":"elimagecontext","link":"#elimagecontext","children":[]}]},{"level":2,"title":"摄像头配置","slug":"摄像头配置","link":"#摄像头配置","children":[]},{"level":2,"title":"摄像头采集数据处理","slug":"摄像头采集数据处理","link":"#摄像头采集数据处理","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"快手·移动端音视频开发实战/14｜iOS平台如何采集视频画面？.md","filePath":"快手·移动端音视频开发实战/14｜iOS平台如何采集视频画面？.md","lastUpdated":1795563308000}'),t={name:"快手·移动端音视频开发实战/14｜iOS平台如何采集视频画面？.md"};function i(l,a,o,r,c,u){return s(),n("div",null,[...a[0]||(a[0]=[p(`<h1 id="_14-ios平台如何采集视频画面" tabindex="-1">14 | iOS平台如何采集视频画面？ <a class="header-anchor" href="#_14-ios平台如何采集视频画面" aria-label="Permalink to &quot;14 | iOS平台如何采集视频画面？&quot;">​</a></h1><p>你好，我是展晓凯。今天我们一起来学习 iOS 平台的视频画面采集。</p><p>前面我们学习的音频采集与编码的方法，可以用来实现音频录制器的功能。但如果要完成视频录制器的功能我们还需要掌握视频采集与编码方面的内容，所以从今天开始我们来学习如何采集视频的画面。</p><p>采集到视频画面之后一般会给用户预览出来，这就要结合之前我们学过的视频画面渲染方面的知识，再加上视频的编码，这样就可以在用户点击录制的时候给视频画面编码并且存储到本地了。这节课我们就先来一起学习在 iOS 平台如何采集视频画面。</p><h2 id="视频框架-elimage-架构设计" tabindex="-1">视频框架 ELImage 架构设计 <a class="header-anchor" href="#视频框架-elimage-架构设计" aria-label="Permalink to &quot;视频框架 ELImage 架构设计&quot;">​</a></h2><p>在 iOS 平台使用 Camera 来采集视频画面的 API 接口比较简单，但要设计出一个优秀的、可扩展的架构，也不是一件容易的事情。所以这节课我会带你设计并实现出一个架构，这个架构基于摄像头采集驱动，中间可以支持视频特效处理，最终用 OpenGL ES 渲染到 UIView 上，且支持扩展插入编码节点。我们先来看一下整体的架构图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/14/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/14/1.png" alt=""></a></p><ul><li>架构图</li></ul><p>左边第一个节点是用系统提供的 Camera 接口，采集出一帧内存中的图像，然后将这个图像上传到显存中成为 YUV 的纹理对象，最后将这个 YUV 格式的纹理重新渲染到一个 RGBA 的纹理上。接着将这个 RGBA 类型的纹理对象传到中间的 Filters 节点，这个节点内部会使用OpenGL ES 来处理这个纹理对象，最后输出一个纹理对象到下面的节点。</p><p>下一级节点是 GLImageView 或将来扩展出来的组件 VideoEncoder，拿到中间 Filters 节点输出之后，进行屏幕渲染或者编码操作。这样一帧图像就从采集、处理到最后预览让用户看到就完成了，并且可以满足我们之后做编码以及图像处理的需求。</p><p>继续看图，你会发现 Camera 和 Filter 这些节点是可以输出纹理对象的，也就是它们的目标纹理对象要作为后一级节点的输入纹理对象；另外，Filter、GLImageView 以及 VideoEncoder需要上一级节点提供输入纹理对象。通过以上两个特点，我们就可以抽象出两个规则。</p><ol><li><p>凡是需要输入纹理对象的，都是 Input 类型。</p></li><li><p>凡是需要向后级节点输出纹理对象的，都是 Output 类型。</p></li></ol><h3 id="elimageinput" tabindex="-1">ELImageInput <a class="header-anchor" href="#elimageinput" aria-label="Permalink to &quot;ELImageInput&quot;">​</a></h3><p>基于规则一，我们可以定义出 ELImageInput 这样一个 Protocol，因为需要别的组件给它输入纹理对象，所以这个 Protocol 里面定义了两个方法，第一个方法是设置输入的纹理对象。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- (void)setInputTexture:(ELImageTextureFrame *)textureFrame;</span></span></code></pre></div><p>节点中的 Filter、GLImageView 以及 VideoEncoder 都属于 ELImageInput 的类型，所以都应该实现这个方法，在这个方法的实现中应该将输入纹理对象保存为一个属性，等绘制的时候使用。此外，这些节点还有一个共同点，就是都需要做渲染操作，所以接下来第二个方法是执行渲染操作。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- (void)newFrameReadyAtTime:(CMTime)frameTime timimgInfo:(CMSampleTimingInfo)timi</span></span></code></pre></div><p>这是上一级节点（实际上是一个 Output 节点）处理完毕之后要调用的方法，在这个方法的实现中可以完成渲染操作。</p><h3 id="elimageoutput" tabindex="-1">ELImageOutput <a class="header-anchor" href="#elimageoutput" aria-label="Permalink to &quot;ELImageOutput&quot;">​</a></h3><p>基于规则二，我们再建立一个类——ELImageOutput，这个类可以向自己的后级节点输出目标纹理对象，其中 Camera、Filter 节点是需要继承自这个类。根据这个特点我们建立两个属性，一个是渲染目标的纹理对象，一个是后级节点列表，代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ELImageTextureFrame *outputTexture;</span></span>
<span class="line"><span>NSMutableArray *targets;</span></span></code></pre></div><p>为什么后级节点是列表类型的呢？</p><p>因为后级节点可能有多个目标对象，比如 Filter 节点，既要输出给 GLImageView，又要输出给 VideoEncoder，而这个 targets 里面的对象，实际上就是之前定义的协议 ELImageInput 类型的对象，因为 Output 节点的后级肯定是一个 Input 类型的对象。既然有一个 targets，就需要提供增加和删除目标节点的方法。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- (void)addTarget:(id&lt;​ELImageInput&gt;)target;</span></span>
<span class="line"><span>- (void)removeTarget:(id&lt;​ELImageInput&gt;)target;</span></span></code></pre></div><p>我们用这两个方法来操作 targets 属性。</p><p>每一个真正继承这个类的节点，执行渲染过程结束之后，就会遍历 targets 里面所有的目标节点（即 ELImageInput）执行设置输出纹理对象的方法，然后执行下一个节点的渲染过程。代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//Do Render Work</span></span>
<span class="line"><span>for (id&lt;​ELImageInput&gt; currentTarget in targets){</span></span>
<span class="line"><span>   [currentTarget setInputTexture:outputTextureFrame];</span></span>
<span class="line"><span>   [currentTarget newFrameReadyAtTime:frameTime timimgInfo:timimgInfo];</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="elimageprogram" tabindex="-1">ELImageProgram <a class="header-anchor" href="#elimageprogram" aria-label="Permalink to &quot;ELImageProgram&quot;">​</a></h3><p>每一个节点的处理都是一个 OpenGL 的渲染过程，所以每个节点都需要建立一个GLProgram。我们不可能在每一个节点里面都去分别书写编译 Shader、链接 Program 等代码，所以要先抽取出一个类，取名为 ELImageProgram（EL 是整个项目的前缀），把GLProgram 的构建、查找属性、使用等这些操作以面向对象的形式封装起来，每一个节点都会组合这个类。</p><h3 id="elimagetextureframe" tabindex="-1">ELImageTextureFrame <a class="header-anchor" href="#elimagetextureframe" aria-label="Permalink to &quot;ELImageTextureFrame&quot;">​</a></h3><p>每一个节点的输入都是一个纹理对象（实际上是一个纹理 ID），使用 GLProgram 将这个纹理对象渲染到一个目标纹理对象的时候，还需要建立一个帧缓存对象（FBO），并且要将这个目标纹理对象 Attach 到这个帧缓存对象上。所以这里我们抽取一个类，取名为ELImageTextureFrame，将纹理对象和帧缓存对象的创建、绑定、销毁等操作，以面向对象的方式封装起来，让每一个节点使用起来都更加方便。</p><h3 id="elimagecontext" tabindex="-1">ELImageContext <a class="header-anchor" href="#elimagecontext" aria-label="Permalink to &quot;ELImageContext&quot;">​</a></h3><p>要想使用 OpenGL ES，必须有上下文以及关联的线程，之前我们也提到过 iOS 平台为OpenGL ES 提供了 EAGL 作为 OpenGL ES 的上下文。后面我们书写编码器组件的时候，因为不希望它阻塞预览线程，所以需要单独开辟一个编码线程，也需要一个额外的 OpenGL 上下文，并且需要和渲染线程共享 OpenGL 上下文。只有这样，在编码线程中才可以正确访问到预览线程中的纹理对象、帧缓存对象。</p><p>所以我们抽取一个类，取名叫做 ELImageContext，来封装 EAGLContext 和渲染线程。因为可能多个对象都要在调用线程和 OpenGL ES 的线程之间进行切换，所以需要给这个类书写一个静态方法，获得渲染线程的 OpenGL 上下文，并且提供静态方法可以得到这个dispatch_queue，让一些 OpenGL ES 的操作可以直接在这个线程中执行，具体的代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+ (void)useImageProcessingContext;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>   [[ELImageContext sharedImageProcessingContext] useAsCurrentContext];</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>- (void)useAsCurrentContext;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>   EAGLContext *imageProcessingContext = [self context];</span></span>
<span class="line"><span>   if ([EAGLContext currentContext] != imageProcessingContext)</span></span>
<span class="line"><span>   {</span></span>
<span class="line"><span>       [EAGLContext setCurrentContext:imageProcessingContext];</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>基于以上分析，我们画出了对应的类图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/14/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/14/2.png" alt=""></a></p><p>GLImageView 部分，你可以回顾之前视频渲染方面的内容，这里也就不再赘述了。第 18节课我们将实现 VideoEncoder，后面你可以自己去实现 Filter，所以这节课我们只实现Camera。Camera 的实现我会分两部分讲解，第一部分是摄像头的配置，第二部分是将摄像头采集到的 YUV 数据转换为纹理对象。</p><h2 id="摄像头配置" tabindex="-1">摄像头配置 <a class="header-anchor" href="#摄像头配置" aria-label="Permalink to &quot;摄像头配置&quot;">​</a></h2><p>我们一直反复强调，在 iOS 平台只要是与硬件相关的使用都要从会话开始配置，所以摄像头这里需要配置 AVCaptureSession。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AVCaptureSession* captureSession;</span></span>
<span class="line"><span>captureSession = [[AVCaptureSession alloc] init];</span></span></code></pre></div><p>然后需要配置出 AVCaptureDeviceInput，这个对象代表了我们要使用哪个摄像头，比如使用前置摄像头。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AVCaptureDevice * captureDevice = nil;</span></span>
<span class="line"><span>NSArray *devices = [AVCaptureDevice devicesWithMediaType:AVMediaTypeVideo];</span></span>
<span class="line"><span>for (AVCaptureDevice *device in devices) {</span></span>
<span class="line"><span>   if ([device position] == AVCaptureDevicePositionFront) {</span></span>
<span class="line"><span>       captureDevice = device;</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>captureInput = [[AVCaptureDeviceInput alloc] initWithDevice:captureDevice error:n</span></span></code></pre></div><p>接着要配置出 AVCaptureVideoDataOutput，这个对象用来处理摄像头采集到的数据。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dispatch_queue_t dataCallbackQueue;</span></span>
<span class="line"><span>dataCallbackQueue = dispatch_queue_create(&quot;dataCallbackQueue&quot;,</span></span>
<span class="line"><span>       DISPATCH_QUEUE_SERIAL);</span></span>
<span class="line"><span>captureOutput = [[AVCaptureVideoDataOutput alloc] init];</span></span>
<span class="line"><span>[_captureOutput setSampleBufferDelegate:self queue:dataCallbackQueue];</span></span></code></pre></div><p>构建出 captureOutput 这个实例之后，要想获取摄像头采集的数据，就需要传入类型为AVCaptureVideoDataOutputSampleBufferDelegate 的实例和一个 dispatch_queue。</p><p>接下来，我们需要设置一下像素格式，默认使用 YUVFullRange 的表示格式，所谓的FullRange，表示 YUV 的取值范围是 0 到 255；还有一种是 YUVVideoRange 的表示格式，为了防止溢出，我们把 YUV 的取值范围设置成 16 到 235。Range 的类型会决定 YUV 格式转换为 RGBA 格式时使用的矩阵，所以这里我们要根据支持的格式来设置，并且记录设置的格式，之后用来确定 YUV 到 RGBA 的转换矩阵。</p><p>接着将 captureInput 实例和 captureOutput 实例配置到 CaptureSession 中。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if ([self.captureSession canAddInput:self.captureInput]) {</span></span>
<span class="line"><span>    [self.captureSession addInput:self.captureInput];</span></span>
<span class="line"><span> }</span></span>
<span class="line"><span>if ([self.captureSession canAddOutput:self.captureOutput]) {</span></span>
<span class="line"><span>    [self.captureSession addOutput:self.captureOutput];</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>然后调用 captureSession 设置分辨率的方法，你可以看一下常见的分辨率以及设置代码。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NSString* highResolution = AVCaptureSessionPreset1280x720;</span></span>
<span class="line"><span>NSString* lowResolution = AVCaptureSessionPreset640x480;</span></span>
<span class="line"><span>[_captureSession setSessionPreset:[NSString stringWithString: highResolution]];</span></span></code></pre></div><p>接着调用 CaptureSession 的 beginConfiguration 方法，配置整个摄像头会话，最后取出captureOutput 里面的 AVCaptureConnection，来配置摄像头输出的方向，这是非常重要的，如果不配置这个参数，摄像头默认输出横向的图片，我们使用代码把它设置成纵向图片输出。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>conn.videoOrientation = AVCaptureVideoOrientationPortrait;</span></span></code></pre></div><p>当然，也可以给 CaptureInput 设置帧率等信息，这里就不再赘述。</p><h2 id="摄像头采集数据处理" tabindex="-1">摄像头采集数据处理 <a class="header-anchor" href="#摄像头采集数据处理" aria-label="Permalink to &quot;摄像头采集数据处理&quot;">​</a></h2><p>前面我们已经实现了 AVCaptureVideoDataOutputSampleBufferDelegate 这个协议，重写了接收摄像头采集数据的方法，签名如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-(void) captureOutput:(AVCaptureOutput*)captureOutput</span></span>
<span class="line"><span>       didOutputSampleBuffer:(CMSampleBufferRef)sampleBuffer</span></span>
<span class="line"><span>       fromConnection:(AVCaptureConnection*)connection</span></span></code></pre></div><p>这个方法会把具体是哪一个 captureOutput 以及 connection 返回过来，但是最重要的其实是CMSampleBuffer 类型的 sampleBuffer，这里面存储着摄像头采集到的图像。一个CMSampleBuffer 由以下三部分组成：</p><ul><li><p>CMTime，代表这一帧图像的时间。</p></li><li><p>CMVideoFormatDescription，代表对这一帧图像格式的描述。</p></li><li><p>CVPixelBuffer，代表这一帧图像的具体数据。</p></li></ul><p>在这个回调函数里，我们需要完成从摄像头采集到图像渲染的全过程，而渲染部分会使用OpenGL ES 来操作。</p><p>之前我们也提到过一个问题，iOS 平台不允许 App 进入后台的时候还执行 OpenGL 渲染，通用的处理方式就是之前在播放器中用到的方式，分别注册 applicationWillResignActive 和applicationDidBecomeActive 的通知，在这两个方法中将这个类中的 shouldEnableOpenGL属性设置为 NO 和 YES。然后在回调函数中判断这个变量，决定是否可以执行 OpenGL 的操作。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-(void) captureOutput:(AVCaptureOutput*)captureOutput didOutputSampleBuffer:</span></span>
<span class="line"><span>     (CMSampleBufferRef)sampleBuffer fromConnection:</span></span>
<span class="line"><span>     (AVCaptureConnection*)connection {</span></span>
<span class="line"><span>   if (self.shouldEnableOpenGL) {</span></span>
<span class="line"><span>       if (dispatch_semaphore_wait(_frameRenderingSemaphore,</span></span>
<span class="line"><span>              DISPATCH_TIME_NOW) != 0) {</span></span>
<span class="line"><span>           return;</span></span>
<span class="line"><span>       }</span></span>
<span class="line"><span>       CFRetain(sampleBuffer);</span></span>
<span class="line"><span>       runAsyncOnVideoProcessingQueue(^{</span></span>
<span class="line"><span>           [self processVideoSampleBuffer:sampleBuffer];</span></span>
<span class="line"><span>           CFRelease(sampleBuffer);</span></span>
<span class="line"><span>           dispatch_semaphore_signal(_frameRenderingSemaphore);</span></span>
<span class="line"><span>       });</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>代码显示，首先要判断这个布尔型的变量，如果是 NO 的话，就不执行任何操作；如果是YES 的话，要保证上一次渲染执行结束了（通过 dispatch_semaphore 的 wait 来确定）才可以执行本次渲染操作。</p><p>执行渲染操作的时候首先要使用 CFRetain 锁定这个 sampleBuffer，因为真正使用sampleBuffer 的地方是在 OpenGL ES 线程中，只有这里 Retain 住才能保证 sampleBuffer 不被污染，等这一次 OpenGL ES 的渲染操作结束以后，再使用 CFRelease 释放这个sampleBuffer。最后给 semaphore 发一个 signal 指令。</p><p>接下来我们看一下真正的渲染操作，也就是方法 processVideoSampleBuffer 的实现，这个方法需要将 sampleBuffer 对象渲染成为一个纹理对象，然后调用后续的 targets 节点进行渲染。</p><p>我们先取出这个 sampleBuffer 中的图像数据，即它的属性 CVPixelBuffer，然后我们需要确定这个 CVPixelBuffer 里面 YUV 转换成 RGB 的矩阵。我们根据两方面的内容来确定这个矩阵。</p><ul><li><p>给摄像头配置的像素格式，是 YUVFullRange 还是 YUVVideoRange；</p></li><li><p>取出 PixelBuffer 里面的 YUV 转换类型，我们判断这个类型是 ITU601 还是 ITU709 格式，ITU601 是 SDTV 的标准，而 ITU709 是 HDTV 的标准，因为标清与高清对应的 YUV 转换为 RGB 的矩阵是不同的。</p></li></ul><p>这两方面共同决定了 YUV 转换成 RGB 的矩阵，其中只有 ITU601 分为 YUVFullRange 和YUVVideoRange 两种，而 ITU709 就只有一种，根据组合从以下三个矩阵中选出合适的矩阵。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GLfloat colorConversion601Default[] = {</span></span>
<span class="line"><span>   1.164,  1.164,   1.164,</span></span>
<span class="line"><span>   0.0,    -0.392,  2.017,</span></span>
<span class="line"><span>   1.596, -0.813,   0.0,</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>GLfloat colorConversion601FullRangeDefault[] = {</span></span>
<span class="line"><span>   1.0,    1.0,     1.0,</span></span>
<span class="line"><span>   0.0,    -0.343, 1.765,</span></span>
<span class="line"><span>   1.4,    -0.711, 0.0,</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>GLfloat colorConversion709Default[] = {</span></span>
<span class="line"><span>   1.164,  1.164,   1.164,</span></span>
<span class="line"><span>   0.0,    -0.213,  2.112,</span></span>
<span class="line"><span>   1.793, -0.533,   0.0,</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>准备工作完成之后，接下来就进入真正渲染过程。</p><p>先绑定 OpenGL ES 的上下文，需要调用前面我们封装的 ELImageContext 绑定上下文的方法。然后创建这个节点的输出纹理对象，就是构建一个 ELImageTextureFrame 对象，并且激活这个纹理对象（代表这个渲染过程的目标就是这个纹理对象）。</p><p>准备输入纹理，要将 CVPixelBuffer 中的 YUV 数据关联到两个纹理 ID 上。如果是在其他平台上，只能通过 OpenGL ES 提供的 glTexImage2D 方法，将内存中的数据上传到显卡的一个纹理 ID 上。但是这种内存和显存之间的数据交换效率是比较低的，在 iOS 平台的 CoreVideoframework 中提供了 CVOpenGLESTextureCacheCreateTextureFromImage 方法，可以使整个交换过程更加高效。</p><p>由于 CVPixelBuffer 内部数据是 YUV 数据格式的，所以可分配以下两个纹理对象分别存储 Y和 UV 的数据。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CVOpenGLESTextureRef luminanceTextureRef = NULL;</span></span>
<span class="line"><span>CVOpenGLESTextureRef chrominanceTextureRef = NULL;</span></span></code></pre></div><p>需要在使用 CVPixelBuffer 这块内存区域之前，先锁定这个对象，使用完毕之后解锁。以下代码可锁定这个 PixelBuffer。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CVPixelBufferLockBaseAddress(pixelBuffer, 0);</span></span></code></pre></div><p>然后拿出这里面的 Y 通道部分的内容，上传到 luminanceTexture 里。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CVOpenGLESTextureCacheCreateTextureFromImage(</span></span>
<span class="line"><span>       kCFAllocatorDefault, coreVideoTextureCache, pixelBuffer,</span></span>
<span class="line"><span>       NULL, GL_TEXTURE_2D, GL_LUMINANCE, bufferWidth,</span></span>
<span class="line"><span>       bufferHeight, GL_LUMINANCE, GL_UNSIGNED_BYTE, 0,</span></span>
<span class="line"><span>       &amp;luminanceTextureRef);</span></span></code></pre></div><p>代码中传入了 pixelBuffer 以及格式 GL_LUMINANCE，还需要传入宽和高。这样这个 API 内部就知道访问 pixelBuffer 的哪部分数据了，里面还有一个非常重要的参数，就是纹理缓存，而创建的纹理会从这个纹理缓存中拿出来，纹理缓存的创建代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CVOpenGLESTextureCacheCreate(kCFAllocatorDefault, NULL, context, NULL, &amp;coreVideo</span></span></code></pre></div><p>可以看到，创建纹理缓存必须要传入 OpenGL 上下文，所以我们一般在 ELImageContext 中维护一个纹理缓存。使用 Y 通道的数据内容创建出来的纹理对象可以通过CVOpenGLESTextureGetName 来获取出纹理 ID。以下代码可以把 UV 通道部分上传到chrominanceTextureRef 里。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CVOpenGLESTextureCacheCreateTextureFromImage(kCFAllocatorDefault, coreVideoTextur</span></span>
<span class="line"><span>       NULL, GL_TEXTURE_2D, GL_LUMINANCE_ALPHA, bufferWidth/2,</span></span>
<span class="line"><span>       bufferHeight/2, GL_LUMINANCE_ALPHA, GL_UNSIGNED_BYTE, 1,</span></span>
<span class="line"><span>       &amp;chrominanceTextureRef)</span></span></code></pre></div><p>YUV420P 格式规定，每四个像素会有一个 U 和一个 V，用 GL_LUMINANCE_ALPHA 来表示 UV 部分，即 U 放到 Luminance 部分，V 放到 Alpha 部分。理解这一点是非常重要的，因为这关乎后面在 FragmentShader 中如何拿到正确的 YUV 数据。</p><p>接下来，就是实际的渲染了，在渲染过程中需要注意两点，一是确定物体坐标和纹理坐标；二是在 FragmentShader 中，怎么把 YUV 转换成 RGBA 的表示格式。我们先来看如何确定物体坐标和纹理坐标，物体坐标其实是固定的，物体坐标如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GLfloat squareVertices[8] = {</span></span>
<span class="line"><span>     -1.0,  -1.0, //物体左下角</span></span>
<span class="line"><span>      1.0，  -1.0，//物体右下角</span></span>
<span class="line"><span>      -1.0， 1.0， //物体左上角</span></span>
<span class="line"><span>      1.0，  1.0   //物体右上角</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>而确定纹理坐标会麻烦一点，记得我们之前讲过，OpenGL 纹理坐标系和计算机坐标系是不同的吗？所以默认情况下，纹理坐标如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GLfloat textureCoords[8] = {</span></span>
<span class="line"><span>     0.0，1.0，</span></span>
<span class="line"><span>     1.0，1.0，</span></span>
<span class="line"><span>     0.0，0.0，</span></span>
<span class="line"><span>     1.0，0.0</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>进行旋转以及镜像的时候，都是根据这个纹理坐标来实施的。左边第一张图是前置摄像头采集到的图像。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/14/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/14/3.png" alt=""></a></p><p>要想正确地显示，需要先按照顺时针旋转 90 度，由于是前置摄像头，还得做一个镜像处理，所以我们的纹理坐标如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GLfloat textureCoords[8] = {</span></span>
<span class="line"><span>     1.0，0.0，</span></span>
<span class="line"><span>     1.0，1.0，</span></span>
<span class="line"><span>     0.0，0.0，</span></span>
<span class="line"><span>     0.0，1.0</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>如果是后置摄像头，那么我们应顺时针旋转 90 度。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/14/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/14/4.png" alt=""></a></p><p>顺时针旋转 90 度的纹理坐标如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GLfloat textureCoords[8] = {</span></span>
<span class="line"><span>     1.0，1.0，</span></span>
<span class="line"><span>     1.0，0.0，</span></span>
<span class="line"><span>     0.0，1.0，</span></span>
<span class="line"><span>     0.0，0.0</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>这里有一点需要特别注意的是，由于把纹理做了 90 度的旋转，所以目标纹理对象宽高和输入纹理（CVPixelBuffer）的宽高需要对调一下。</p><p>上述纹理坐标是默认摄像头给出的图像纹理坐标，但前面我们给摄像头做过一个特殊的设置，就是给 AVCaptureConnection 设置 videoOrientation 这个参数，摄像头默认是横向视频输出，当把这个参数设置为 Portrait 时，就要求摄像头按照竖直方向输出视频。这时候目标纹理对象的宽高和 CVPixelBuffer 的宽高一致了，那么后置摄像头采集出来的图像直接绘制即可。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/14/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/14/5.png" alt=""></a></p><p>所对应的纹理坐标为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GLfloat textureCoords[8] = {</span></span>
<span class="line"><span>     0.0，1.0，</span></span>
<span class="line"><span>     1.0，1.0，</span></span>
<span class="line"><span>     0.0，0.0，</span></span>
<span class="line"><span>     1.0，0.0</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>而前置摄像头由于镜像的原因，所以绘制过程如下图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/14/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/14/6.png" alt=""></a></p><p>此时的纹理坐标正好和后置摄像头的每一个坐标的 X 点相反。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GLfloat textureCoords[8] = {</span></span>
<span class="line"><span>     1.0，1.0，</span></span>
<span class="line"><span>     0.0，1.0，</span></span>
<span class="line"><span>     1.0，0.0，</span></span>
<span class="line"><span>     0.0，0.0</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>确定物体坐标与纹理坐标之后，我们就来看一下如何在 FragmentShader 中，将 YUV 转换成RGBA。注意：这里是一定要转换为 RGBA 的，因为在 OpenGL 中通用的渲染纹理格式都是RGBA 的，包括纹理处理、渲染到屏幕上以及最终编码器，都是以 RGBA 格式为基础进行转换和处理的。在播放器的部分我们已经做过一次 YUV 转 RGB 的操作，但是由于使用了CoreVideo 这个 framework 下的快速上传，输入的纹理变得不一样了，所以我们来看下具体的 FragmentShader。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>varying highp vec2 textureCoordinate;</span></span>
<span class="line"><span>uniform sampler2D luminanceTexture;</span></span>
<span class="line"><span>uniform sampler2D chrominanceTexture;</span></span>
<span class="line"><span>uniform mediump mat3 colorConversionMatrix;</span></span>
<span class="line"><span>void main(){</span></span>
<span class="line"><span>   mediump vec3 yuv;</span></span>
<span class="line"><span>   lowp vec3 rgb;</span></span>
<span class="line"><span>   yuv.x = texture2D(luminanceTexture, textureCoordinate).r;</span></span>
<span class="line"><span>   yuv.yz = texture2D(chrominanceTexture, textureCoordinate).ra - vec2(0.5, 0.5)</span></span>
<span class="line"><span>   rgb = colorConversionMatrix * yuv;</span></span>
<span class="line"><span>   gl_FragColor = vec4(rgb, 1);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>其中 textureCoordinate 是纹理坐标，而这两个 sampler2D 类型就是从 CVPixelBuffer 里面上传到显存中的纹理对象，3*3 的矩阵就是前面根据像素格式，以及是否为 FullRange 选择的变换矩阵。我们重点看一下如何取出 Y 和 UV。</p><ul><li><p>由于 luminanceTexture 使用的是 GL_LUMINANCE 格式上传上来的纹理，所以这里使用texture2D 函数拿出像素点之后，访问元素 r 就可以拿到 Y 通道的值了。</p></li><li><p>而 UV 通道使用的是 GL_LUMINANCE_ALPHA 格式，通过 texture2D 取出像素点之后，访问元素 r 得到 U 的值，访问元素 a 得到 V 的值。但为什么 UV 值要减去 0.5（换算为 0-255就是减去 127）？这是因为 UV 是色彩分量，当整张图片是黑白的时候，UV 分量是默认值127，所以这里要先减去 127，然后再转换成 RGB，否则会出现色彩不匹配的错误。</p></li></ul><p>最后使用传递进来的转换矩阵乘以 YUV，得到这个像素点的 RGBA 表示格式，并赋值给gl_FragColor。</p><p>到这里，ELImageVideoCamera 这个类的核心逻辑我们就学完了，最终这个节点会输出一个纹理 ID，这个纹理 ID 可以直接渲染到 ELImageView 中让用户看到摄像头预览的效果。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>最后，我们可以一起来回顾一下。</p><p>这节课我们设计并实现出一个 ELImage 视频框架的架构，包含 ELImageInput、ELImageOutput、ELImageProgram、ELImageTextureFrame 和 ELImageContext 五个基础类。然后基于这五个类可以扩展出众多组件。</p><p>我们利用框架核心完成了视频画面的采集，用的就是 ELImageVideoCamera 这个类。这个节点最终会输出一个 RGBA 类型的纹理，这个纹理可以给到后续的 ELImageFilter 节点做美颜处理，最终输出到 ELImageView 中，显示出来，而这个过程就是打开摄像头预览的过程。</p><p>ELImage 这个核心框架很重要，我们需要好好“消化”这部分内容，因为这个视频框架后续会用到，并且基于这个视频框架，我们还会增加一些其他节点，比如 ELImageVideoEncoder 等，也就是当用户点击录制的时候，将纹理 ID 传入到 Encoder 节点就可以录制出视频文件来。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>ELImage 框架还可以扩展出许多其他的节点，组成复杂的场景，比如视频编辑器场景，如果让你书写一个 ELImageMovie 节点，然后与 ELImageFilter 以及 ELImageView 组合成视频编辑器，你将如何完成 ELImageMovie 的设计呢？在评论区中给出你的思考，也欢迎你把这节课分享给更多对音视频感兴趣的朋友，我们一起交流、共同进步。下节课再见！</p>`,117)])])}const h=e(t,[["render",i]]);export{d as __pageData,h as default};
